  /**
   * Implements "Strike 1" of the two-strike loop detection policy: instead of
   * terminating the session, nudge the agent with a recovery message so it has a
   * chance to self-correct. The active loop detection state has already been
   * cleared by the caller, but the cumulative strike count is preserved so a
   * subsequent detection escalates to terminating the session.
   *
   * If continuing would exhaust the remaining turn budget, the session limit is
   * surfaced instead of attempting recovery.
   */
  private async *recoverFromLoop(
    detail: string | undefined,
    signal: AbortSignal,
    prompt_id: string,
    boundedTurns: number,
    displayContent?: PartListUnion,
  ): AsyncGenerator<ServerGeminiStreamEvent, Turn> {
    if (boundedTurns - 1 <= 0) {
      yield { type: GeminiEventType.MaxSessionTurns };
      return new Turn(this.getChat(), prompt_id);
    }

    const recoveryMessage =
      `System: Potential loop detected.${detail ? ` ${detail}` : ''} ` +
      `Please re-evaluate your approach and take a different action to make ` +
      `progress on the user's request.`;

    return yield* this.sendMessageStream(
      [{ text: recoveryMessage }],
      signal,
      prompt_id,
      boundedTurns - 1,
      false,
      displayContent,
    );
  }

